func biFusionSelect(cs ...val) val {
	bestI, bestC := 0, int(^uint(0)>>1)
	for i, c := range cs {
		if i >= 3 {
			break
		}
		v := asI(c)
		if v < bestC {
			bestC = v
			bestI = i
		}
	}
	return vI32(bestI)
}
