func biPair(a, b val) val { return vSpan([]val{a, b}) }
func biPairN(xs ...val) val { return vSpan(append([]val{}, xs...)) }
func biPairFirst(p val) val {
	if p.k != tvSpan || len(p.items) < 1 {
		return vF32(0)
	}
	return p.items[0]
}
func biPairSecond(p val) val {
	if p.k != tvSpan || len(p.items) < 2 {
		return vF32(0)
	}
	return p.items[1]
}
func biPairAt(p val, i val) val {
	// Leaf-aware index into (possibly nested) pair/span (v0.48)
	leaves := biPairLeaves(p)
	idx := asI(i)
	if idx < 0 || idx >= len(leaves) {
		return vF32(0)
	}
	return leaves[idx]
}
func biPairLeaves(p val) []val {
	if p.k != tvSpan {
		return []val{p}
	}
	out := make([]val, 0, len(p.items))
	for _, e := range p.items {
		out = append(out, biPairLeaves(e)...)
	}
	return out
}
func biHwVlenForN(n val) val {
	x := asI(n)
	if x >= 16 {
		return vI32(16)
	}
	if x >= 8 {
		return vI32(8)
	}
	if x >= 4 {
		return vI32(4)
	}
	if x < 0 {
		return vI32(0)
	}
	return vI32(x)
}
func biDynTile(n val) val { return biHwVlenForN(n) }
func clamp01(w float64) float64 {
	if w < 0 {
		return 0
	}
	if w > 1 {
		return 1
	}
	return w
}
func biSoftMux(w, pure, each val) val {
	ww := clamp01(asF(w))
	return vF32(ww*asF(pure) + (1-ww)*asF(each))
}
func biSoftMuxGrad(w, pure, each, dy val) val {
	ww := clamp01(asF(w))
	d := asF(dy)
	return vSpan([]val{
		vF32(d * (asF(pure) - asF(each))),
		vF32(d * ww),
		vF32(d * (1 - ww)),
	})
}
func biSoftMuxGradW(w, pure, each, dy val) val {
	return vF32(asF(dy) * (asF(pure) - asF(each)))
}
func biSoftMuxGradPure(w, pure, each, dy val) val {
	return vF32(asF(dy) * clamp01(asF(w)))
}
func biSoftMuxGradEach(w, pure, each, dy val) val {
	return vF32(asF(dy) * (1 - clamp01(asF(w))))
}
// Full reverse-mode AD over f32 + span kernels (v0.7/0.8) — mirrors internal/ad.
func biGradExpr(expr val, names val, values val) val {
	env := map[string]float64{}
	order := []string{}
	n := len(names.items)
	if len(values.items) < n {
		n = len(values.items)
	}
	for i := 0; i < n; i++ {
		name := names.items[i].s
		if names.items[i].k != tvStr {
			name = fmtVal(names.items[i])
		}
		env[name] = asF(values.items[i])
		order = append(order, name)
	}
	valY, grads, err := evalGradExpr(expr.s, env, order)
	if err != nil {
		panic("grad_expr: " + err.Error())
	}
	out := make([]val, 0, 1+len(order))
	out = append(out, vF32(valY))
	for _, g := range grads {
		out = append(out, vF32(g))
	}
	return vSpan(out)
}
func biGradSum(xs val) val {
	tp := &adTape{}
	ids := make([]int, len(xs.items))
	for i, x := range xs.items {
		ids[i] = tp.cnst(asF(x))
	}
	out := tp.sum(ids)
	g := tp.grad(out)
	res := make([]val, 0, 1+len(ids))
	res = append(res, vF32(tp.nodes[out].v))
	for _, id := range ids {
		res = append(res, vF32(g[id]))
	}
	return vSpan(res)
}
func biGradDot(a, b val) val {
	n := len(a.items)
	if len(b.items) < n {
		n = len(b.items)
	}
	tp := &adTape{}
	as := make([]int, n)
	bs := make([]int, n)
	for i := 0; i < n; i++ {
		as[i] = tp.cnst(asF(a.items[i]))
		bs[i] = tp.cnst(asF(b.items[i]))
	}
	out := tp.dot(as, bs)
	g := tp.grad(out)
	res := make([]val, 0, 1+2*n)
	res = append(res, vF32(tp.nodes[out].v))
	for i := 0; i < n; i++ {
		res = append(res, vF32(g[as[i]]))
	}
	for i := 0; i < n; i++ {
		res = append(res, vF32(g[bs[i]]))
	}
	return vSpan(res)
}
func biGradSpanAdd(a, b val) val {
	n := len(a.items)
	if len(b.items) < n {
		n = len(b.items)
	}
	tp := &adTape{}
	as := make([]int, n)
	bs := make([]int, n)
	zs := make([]int, n)
	for i := 0; i < n; i++ {
		as[i] = tp.cnst(asF(a.items[i]))
		bs[i] = tp.cnst(asF(b.items[i]))
		zs[i] = tp.add(as[i], bs[i])
	}
	out := tp.sum(zs)
	g := tp.grad(out)
	res := make([]val, 0, 1+2*n)
	res = append(res, vF32(tp.nodes[out].v))
	for i := 0; i < n; i++ {
		res = append(res, vF32(g[as[i]]))
	}
	for i := 0; i < n; i++ {
		res = append(res, vF32(g[bs[i]]))
	}
	return vSpan(res)
}
func biGradScale(s, xs val) val {
	tp := &adTape{}
	sid := tp.cnst(asF(s))
	ids := make([]int, len(xs.items))
	zs := make([]int, len(xs.items))
	for i, x := range xs.items {
		ids[i] = tp.cnst(asF(x))
		zs[i] = tp.mul(sid, ids[i])
	}
	out := tp.sum(zs)
	g := tp.grad(out)
	res := make([]val, 0, 2+len(ids))
	res = append(res, vF32(tp.nodes[out].v), vF32(g[sid]))
	for _, id := range ids {
		res = append(res, vF32(g[id]))
	}
	return vSpan(res)
}
func biGradMapMul(s, xs val) val { return biGradScale(s, xs) }

// --- embedded mini reverse-mode AD (mirrors github.com/ericchien/trin/internal/ad) ---
type adKind int

const (
	adConst adKind = iota
	adAdd
	adSub
	adMul
	adDiv
	adNeg
	adMux
	adSum
	adDot
)

type adNode struct {
	k       adKind
	v       float64
	a, b, c int
	args    []int
}

type adTape struct{ nodes []adNode }

func (t *adTape) cnst(v float64) int {
	t.nodes = append(t.nodes, adNode{k: adConst, v: v})
	return len(t.nodes) - 1
}
func (t *adTape) add(a, b int) int {
	t.nodes = append(t.nodes, adNode{k: adAdd, v: t.nodes[a].v + t.nodes[b].v, a: a, b: b})
	return len(t.nodes) - 1
}
func (t *adTape) sub(a, b int) int {
	t.nodes = append(t.nodes, adNode{k: adSub, v: t.nodes[a].v - t.nodes[b].v, a: a, b: b})
	return len(t.nodes) - 1
}
func (t *adTape) mul(a, b int) int {
	t.nodes = append(t.nodes, adNode{k: adMul, v: t.nodes[a].v * t.nodes[b].v, a: a, b: b})
	return len(t.nodes) - 1
}
func (t *adTape) div(a, b int) int {
	t.nodes = append(t.nodes, adNode{k: adDiv, v: t.nodes[a].v / t.nodes[b].v, a: a, b: b})
	return len(t.nodes) - 1
}
func (t *adTape) neg(a int) int {
	t.nodes = append(t.nodes, adNode{k: adNeg, v: -t.nodes[a].v, a: a})
	return len(t.nodes) - 1
}
func (t *adTape) mux(w, pure, each int) int {
	ww := clamp01(t.nodes[w].v)
	v := ww*t.nodes[pure].v + (1-ww)*t.nodes[each].v
	t.nodes = append(t.nodes, adNode{k: adMux, v: v, a: w, b: pure, c: each})
	return len(t.nodes) - 1
}
func (t *adTape) val(id int) float64 { return t.nodes[id].v }

func (t *adTape) sum(elems []int) int {
	var s float64
	for _, id := range elems {
		s += t.nodes[id].v
	}
	cp := append([]int(nil), elems...)
	t.nodes = append(t.nodes, adNode{k: adSum, v: s, args: cp})
	return len(t.nodes) - 1
}
func (t *adTape) dot(as, bs []int) int {
	n := len(as)
	if len(bs) < n {
		n = len(bs)
	}
	var s float64
	args := make([]int, 0, 2*n)
	for i := 0; i < n; i++ {
		s += t.nodes[as[i]].v * t.nodes[bs[i]].v
		args = append(args, as[i])
	}
	for i := 0; i < n; i++ {
		args = append(args, bs[i])
	}
	t.nodes = append(t.nodes, adNode{k: adDot, v: s, c: n, args: args})
	return len(t.nodes) - 1
}
func (t *adTape) grad(out int) []float64 {
	g := make([]float64, len(t.nodes))
	g[out] = 1
	for i := len(t.nodes) - 1; i >= 0; i-- {
		gi := g[i]
		if gi == 0 {
			continue
		}
		nd := t.nodes[i]
		switch nd.k {
		case adAdd:
			g[nd.a] += gi
			g[nd.b] += gi
		case adSub:
			g[nd.a] += gi
			g[nd.b] -= gi
		case adMul:
			g[nd.a] += gi * t.nodes[nd.b].v
			g[nd.b] += gi * t.nodes[nd.a].v
		case adDiv:
			bv := t.nodes[nd.b].v
			g[nd.a] += gi / bv
			g[nd.b] += -gi * t.nodes[nd.a].v / (bv * bv)
		case adNeg:
			g[nd.a] -= gi
		case adMux:
			ww := clamp01(t.nodes[nd.a].v)
			g[nd.a] += gi * (t.nodes[nd.b].v - t.nodes[nd.c].v)
			g[nd.b] += gi * ww
			g[nd.c] += gi * (1 - ww)
		case adSum:
			for _, pid := range nd.args {
				g[pid] += gi
			}
		case adDot:
			nn := nd.c
			for j := 0; j < nn; j++ {
				ai := nd.args[j]
				bi := nd.args[nn+j]
				g[ai] += gi * t.nodes[bi].v
				g[bi] += gi * t.nodes[ai].v
			}
		}
	}
	return g
}

func evalGradExpr(expr string, env map[string]float64, order []string) (float64, []float64, error) {
	tp := &adTape{}
	ids := map[string]int{}
	for k, v := range env {
		ids[k] = tp.cnst(v)
	}
	out, err := adParseBuild(tp, expr, ids)
	if err != nil {
		return 0, nil, err
	}
	g := tp.grad(out)
	gs := make([]float64, len(order))
	for i, name := range order {
		gs[i] = g[ids[name]]
	}
	return tp.nodes[out].v, gs, nil
}

// tiny expression parser for grad_expr
type adLex struct {
	s   string
	i   int
	tok string
	val string
}

func adParseBuild(tp *adTape, expr string, ids map[string]int) (int, error) {
	lx := &adLex{s: expr}
	lx.next()
	return adParseExpr(tp, lx, ids)
}

func (lx *adLex) next() {
	for lx.i < len(lx.s) && (lx.s[lx.i] == ' ' || lx.s[lx.i] == '\t') {
		lx.i++
	}
	if lx.i >= len(lx.s) {
		lx.tok, lx.val = "eof", ""
		return
	}
	c := lx.s[lx.i]
	if c == '=' && lx.i+1 < len(lx.s) && lx.s[lx.i+1] == '>' {
		lx.tok, lx.val = "=>", "=>"
		lx.i += 2
		return
	}
	switch c {
	case '+', '-', '*', '/', '(', ')', ',', '[', ']':
		lx.tok, lx.val = string(c), string(c)
		lx.i++
		return
	}
	if c >= '0' && c <= '9' || c == '.' {
		j := lx.i
		for j < len(lx.s) && ((lx.s[j] >= '0' && lx.s[j] <= '9') || lx.s[j] == '.') {
			j++
		}
		lx.tok, lx.val = "num", lx.s[lx.i:j]
		lx.i = j
		return
	}
	if c == '_' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' {
		j := lx.i + 1
		for j < len(lx.s) {
			ch := lx.s[j]
			if ch == '_' || ch >= 'A' && ch <= 'Z' || ch >= 'a' && ch <= 'z' || ch >= '0' && ch <= '9' {
				j++
				continue
			}
			break
		}
		lx.tok, lx.val = "id", lx.s[lx.i:j]
		lx.i = j
		return
	}
	lx.tok, lx.val = "err", string(c)
}

func adParseExpr(tp *adTape, lx *adLex, ids map[string]int) (int, error) {
	return adParseAdd(tp, lx, ids)
}
func adParseAdd(tp *adTape, lx *adLex, ids map[string]int) (int, error) {
	left, err := adParseMul(tp, lx, ids)
	if err != nil {
		return 0, err
	}
	for lx.tok == "+" || lx.tok == "-" {
		op := lx.tok
		lx.next()
		right, err := adParseMul(tp, lx, ids)
		if err != nil {
			return 0, err
		}
		if op == "+" {
			left = tp.add(left, right)
		} else {
			left = tp.sub(left, right)
		}
	}
	return left, nil
}
func adParseMul(tp *adTape, lx *adLex, ids map[string]int) (int, error) {
	left, err := adParseUnary(tp, lx, ids)
	if err != nil {
		return 0, err
	}
	for lx.tok == "*" || lx.tok == "/" {
		op := lx.tok
		lx.next()
		right, err := adParseUnary(tp, lx, ids)
		if err != nil {
			return 0, err
		}
		if op == "*" {
			left = tp.mul(left, right)
		} else {
			left = tp.div(left, right)
		}
	}
	return left, nil
}
func adParseUnary(tp *adTape, lx *adLex, ids map[string]int) (int, error) {
	if lx.tok == "-" {
		lx.next()
		x, err := adParseUnary(tp, lx, ids)
		if err != nil {
			return 0, err
		}
		return tp.neg(x), nil
	}
	if lx.tok == "+" {
		lx.next()
		return adParseUnary(tp, lx, ids)
	}
	return adParsePrimary(tp, lx, ids)
}
func adParseSpan(tp *adTape, lx *adLex, ids map[string]int) ([]int, error) {
	if lx.tok != "[" {
		return nil, fmt.Errorf("want [")
	}
	lx.next()
	var elems []int
	if lx.tok != "]" {
		for {
			e, err := adParseExpr(tp, lx, ids)
			if err != nil {
				return nil, err
			}
			elems = append(elems, e)
			if lx.tok == "," {
				lx.next()
				continue
			}
			break
		}
	}
	if lx.tok != "]" {
		return nil, fmt.Errorf("want ]")
	}
	lx.next()
	return elems, nil
}


// adParseSpanExpr parses a span literal or span_add/scale/map_mul/map/zip_with/scan call returning element tape ids.
// Caller must leave token at start of span expression ( [ or id ).
func adParseSpanExpr(tp *adTape, lx *adLex, ids map[string]int) ([]int, error) {
	if lx.tok == "[" {
		return adParseSpan(tp, lx, ids)
	}
	if lx.tok != "id" {
		return nil, fmt.Errorf("want span")
	}
	name := lx.val
	lx.next()
	if lx.tok != "(" {
		return nil, fmt.Errorf("want (")
	}
	lx.next()
	switch name {
	case "span_add":
		as, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		bs, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		n := len(as)
		if len(bs) < n {
			n = len(bs)
		}
		out := make([]int, n)
		for i := 0; i < n; i++ {
			out[i] = tp.add(as[i], bs[i])
		}
		return out, nil
	case "scale", "map_mul":
		sid, err := adParseExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		xs, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		out := make([]int, len(xs))
		for i, xid := range xs {
			out[i] = tp.mul(sid, xid)
		}
		return out, nil
	case "map":
		// map((x)=>body, span)
		pname, bodyFn, err := adParseMapLambda(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		xs, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		out := make([]int, len(xs))
		for i, xid := range xs {
			bid, err := bodyFn(xid)
			if err != nil {
				return nil, err
			}
			_ = pname
			out[i] = bid
		}
		return out, nil
	case "zip_with":
		// zip_with((p0..)=>body, s0..) n-ary N>=2
		params, bodyFn, err := adParseNLambda(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		// parse span args matching arity
		spans := make([][]int, 0, len(params))
		for i := 0; i < len(params); i++ {
			if lx.tok != "," {
				return nil, fmt.Errorf("want ,")
			}
			lx.next()
			sp, err := adParseSpanExpr(tp, lx, ids)
			if err != nil {
				return nil, err
			}
			spans = append(spans, sp)
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		if len(spans) < 2 {
			return nil, fmt.Errorf("zip_with wants >=2 spans")
		}
		n := len(spans[0])
		for _, sp := range spans[1:] {
			if len(sp) < n {
				n = len(sp)
			}
		}
		out := make([]int, n)
		for i := 0; i < n; i++ {
			idsAt := make([]int, len(spans))
			for si := range spans {
				idsAt[si] = spans[si][i]
			}
			bid, err := bodyFn(idsAt)
			if err != nil {
				return nil, err
			}
			out[i] = bid
		}
		return out, nil
	case "filter":
		// filter((x)=>pred, span) — hard keep where pred != 0
		params, bodyFn, err := adParseNLambda(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if len(params) != 1 {
			return nil, fmt.Errorf("filter lambda wants 1 param")
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		xs, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		out := make([]int, 0, len(xs))
		for _, xid := range xs {
			pid, err := bodyFn([]int{xid})
			if err != nil {
				return nil, err
			}
			if tp.val(pid) != 0 {
				out = append(out, xid)
			}
		}
		return out, nil
	case "scan":
		// scan((acc,x)=>body, init, span) — emit intermediate accs
		params, bodyFn, err := adParseNLambda(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if len(params) != 2 {
			return nil, fmt.Errorf("scan lambda wants 2 params")
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		accID, err := adParseExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != "," {
			return nil, fmt.Errorf("want ,")
		}
		lx.next()
		xs, err := adParseSpanExpr(tp, lx, ids)
		if err != nil {
			return nil, err
		}
		if lx.tok != ")" {
			return nil, fmt.Errorf("want )")
		}
		lx.next()
		out := make([]int, len(xs))
		for i, xid := range xs {
			bid, err := bodyFn([]int{accID, xid})
			if err != nil {
				return nil, err
			}
			accID = bid
			out[i] = bid
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unknown span fn %s", name)
	}
}

// adParseZipWithLambda parses (x,y)=>body into a binary reparse closure.
func adParseZipWithLambda(tp *adTape, lx *adLex, ids map[string]int) (string, string, func(int, int) (int, error), error) {
	params, bodyFn, err := adParseNLambda(tp, lx, ids)
	if err != nil {
		return "", "", nil, err
	}
	if len(params) != 2 {
		return "", "", nil, fmt.Errorf("zip_with lambda wants 2 params")
	}
	fn := func(xid, yid int) (int, error) {
		return bodyFn([]int{xid, yid})
	}
	return params[0], params[1], fn, nil
}

// adParseNLambda parses (p0,p1,... )=>body into a reparse closure over param ids.
func adParseNLambda(tp *adTape, lx *adLex, ids map[string]int) ([]string, func([]int) (int, error), error) {
	if lx.tok != "(" {
		return nil, nil, fmt.Errorf("lambda wants (")
	}
	lx.next()
	var params []string
	if lx.tok == "id" {
		for {
			if lx.tok != "id" {
				return nil, nil, fmt.Errorf("lambda param")
			}
			params = append(params, lx.val)
			lx.next()
			if lx.tok == "," {
				lx.next()
				continue
			}
			break
		}
	}
	if lx.tok != ")" {
		return nil, nil, fmt.Errorf("lambda wants )")
	}
	lx.next()
	if lx.tok != "=>" {
		return nil, nil, fmt.Errorf("lambda wants =>")
	}
	lx.next()
	bodySrc, err := adCaptureBody(lx)
	if err != nil {
		return nil, nil, err
	}
	fn := func(argIDs []int) (int, error) {
		if len(argIDs) != len(params) {
			return 0, fmt.Errorf("lambda arity mismatch")
		}
		child := map[string]int{}
		for k, v := range ids {
			child[k] = v
		}
		for i, p := range params {
			child[p] = argIDs[i]
		}
		return adParseBuild(tp, bodySrc, child)
	}
	return params, fn, nil
}

// adParseMapLambda parses (x)=>... leaving body as a closure that binds x id.
func adParseMapLambda(tp *adTape, lx *adLex, ids map[string]int) (string, func(int) (int, error), error) {
	if lx.tok != "(" {
		return "", nil, fmt.Errorf("map lambda wants (")
	}
	lx.next()
	if lx.tok != "id" {
		return "", nil, fmt.Errorf("map lambda param")
	}
	pname := lx.val
	lx.next()
	if lx.tok != ")" {
		return "", nil, fmt.Errorf("map lambda wants )")
	}
	lx.next()
	if lx.tok != "=>" {
		return "", nil, fmt.Errorf("map lambda wants =>")
	}
	lx.next()
	// parse body expression once relative to ids plus param placeholder — we need re-parse per element.
	// Capture source slice of body by re-tokenizing from current position is hard.
	// Instead: parse body AST-like into tape with a temporary free var id that we replace... 
	// Practical approach: parse body once into a *deferred* expression tree using parallel mini on remaining tokens.
	// Simplest workable: read body as text via token replay — parse body with param as fresh cnst then we can't reuse.
	// Rebuild: parse body into tape nodes where param refers to a fixed placeholder const that we substitute? No, graph edges point to placeholder.
	// Correct approach: body is reparsed from a recorded string.
	start := lx.i - len(lx.val) // weak
	_ = start
	// Record remaining source from current token start:
	// lx.i is already past current token start for previous next(). Track body source:
	// Re-lex body by consuming tokens into a string builder from current position in original:
	// Actually save lx.i before parsing, parse body once into an expression built as func of param by using recursive adParse with param id.

	// Strategy: first parse with a temporary binding of pname -> a sentinal const; then that won't generalize.
	// Better: parse body into a lightweight ADExpr tree, then compile per element.

	// Lightweight: body reparse per element from saved source substring.
	// Find body end by counting tokens until we hit "," or ")" at depth 0 of () and [].
	bodySrc, err := adCaptureBody(lx)
	if err != nil {
		return "", nil, err
	}
	fn := func(xid int) (int, error) {
		child := map[string]int{}
		for k, v := range ids {
			child[k] = v
		}
		child[pname] = xid
		return adParseBuild(tp, bodySrc, child)
	}
	return pname, fn, nil
}

// adCaptureBody consumes tokens that form one expression and returns the matching source substring.
func adCaptureBody(lx *adLex) (string, error) {
	// start index of current token in original string
	// Reconstruct: after last next(), token starts at lx.i - len(lx.val) for multi-char, or lx.i-1 for single.
	// Safer: remember start before any body token — caller just did lx.next() after => so current tok is first of body.
	start := adTokenStart(lx)
	depthParen, depthBrack := 0, 0
	if lx.tok == "eof" {
		return "", fmt.Errorf("empty map body")
	}
	for {
		switch lx.tok {
		case "(":
			depthParen++
		case ")":
			if depthParen == 0 && depthBrack == 0 {
				// body ends before this
				end := adTokenStart(lx)
				return strings.TrimSpace(lx.s[start:end]), nil
			}
			depthParen--
		case "[":
			depthBrack++
		case "]":
			depthBrack--
		case ",":
			if depthParen == 0 && depthBrack == 0 {
				end := adTokenStart(lx)
				return strings.TrimSpace(lx.s[start:end]), nil
			}
		case "eof":
			return "", fmt.Errorf("unterminated map body")
		}
		lx.next()
	}
}

func adTokenStart(lx *adLex) int {
	if lx.tok == "eof" {
		return lx.i
	}
	return lx.i - len(lx.val)
}

func adParsePrimary(tp *adTape, lx *adLex, ids map[string]int) (int, error) {
	switch lx.tok {
	case "num":
		s := lx.val
		lx.next()
		var f float64
		fmt.Sscan(s, &f)
		return tp.cnst(f), nil
	case "id":
		name := lx.val
		lx.next()
		if lx.tok == "(" {
			lx.next()
			// sum/dot may take span literals
			if name == "sum" {
				var elems []int
				// sum([..]) | sum(span_add/scale/map_mul(...)) | sum(e0, e1, ...)
				if lx.tok == "[" {
					var err error
					elems, err = adParseSpan(tp, lx, ids)
					if err != nil {
						return 0, err
					}
				} else if lx.tok == "id" {
					// look ahead: id( → may be span producer
					savedI, savedTok, savedVal := lx.i, lx.tok, lx.val
					fname := lx.val
					lx.next()
					if lx.tok == "(" && (fname == "span_add" || fname == "scale" || fname == "map_mul" || fname == "map" || fname == "zip_with" || fname == "scan" || fname == "filter") {
						// rewind to id and use span expr parser
						lx.i, lx.tok, lx.val = savedI, savedTok, savedVal
						var err error
						elems, err = adParseSpanExpr(tp, lx, ids)
						if err != nil {
							return 0, err
						}
					} else {
						// rewind; parse scalar arg list
						lx.i, lx.tok, lx.val = savedI, savedTok, savedVal
						for {
							a, err := adParseExpr(tp, lx, ids)
							if err != nil {
								return 0, err
							}
							elems = append(elems, a)
							if lx.tok == "," {
								lx.next()
								continue
							}
							break
						}
					}
				} else {
					for {
						a, err := adParseExpr(tp, lx, ids)
						if err != nil {
							return 0, err
						}
						elems = append(elems, a)
						if lx.tok == "," {
							lx.next()
							continue
						}
						break
					}
				}
				if lx.tok != ")" {
					return 0, fmt.Errorf("want )")
				}
				lx.next()
				return tp.sum(elems), nil
			}
			if name == "dot" {
				as, err := adParseSpanExpr(tp, lx, ids)
				if err != nil {
					return 0, err
				}
				if lx.tok != "," {
					return 0, fmt.Errorf("want ,")
				}
				lx.next()
				bs, err := adParseSpanExpr(tp, lx, ids)
				if err != nil {
					return 0, err
				}
				if lx.tok != ")" {
					return 0, fmt.Errorf("want )")
				}
				lx.next()
				return tp.dot(as, bs), nil
			}
			if name == "reduce" || name == "fold" {
				// reduce/fold((acc,x)=>body, init, span)
				px, py, bodyFn, err := adParseZipWithLambda(tp, lx, ids)
				if err != nil {
					return 0, err
				}
				_ = px
				_ = py
				if lx.tok != "," {
					return 0, fmt.Errorf("want ,")
				}
				lx.next()
				accID, err := adParseExpr(tp, lx, ids)
				if err != nil {
					return 0, err
				}
				if lx.tok != "," {
					return 0, fmt.Errorf("want ,")
				}
				lx.next()
				xs, err := adParseSpanExpr(tp, lx, ids)
				if err != nil {
					return 0, err
				}
				if lx.tok != ")" {
					return 0, fmt.Errorf("want )")
				}
				lx.next()
				for _, xid := range xs {
					bid, err := bodyFn(accID, xid)
					if err != nil {
						return 0, err
					}
					accID = bid
				}
				return accID, nil
			}
			var args []int
			if lx.tok != ")" {
				for {
					a, err := adParseExpr(tp, lx, ids)
					if err != nil {
						return 0, err
					}
					args = append(args, a)
					if lx.tok == "," {
						lx.next()
						continue
					}
					break
				}
			}
			if lx.tok != ")" {
				return 0, fmt.Errorf("want )")
			}
			lx.next()
			if name == "soft_mux" && len(args) == 3 {
				return tp.mux(args[0], args[1], args[2]), nil
			}
			return 0, fmt.Errorf("unknown fn %s", name)
		}
		id, ok := ids[name]
		if !ok {
			return 0, fmt.Errorf("unknown var %s", name)
		}
		return id, nil
	case "[":
		// bare span not scalar
		return 0, fmt.Errorf("bare span; use sum/dot")
	case "(":
		lx.next()
		e, err := adParseExpr(tp, lx, ids)
		if err != nil {
			return 0, err
		}
		if lx.tok != ")" {
			return 0, fmt.Errorf("want )")
		}
		lx.next()
		return e, nil
	default:
		return 0, fmt.Errorf("bad token %s", lx.val)
	}
}

func biMapMul2(xs val) val {
	out := make([]val, len(xs.items))
	for i, x := range xs.items {
		out[i] = vF32(asF(x) * 2)
	}
	return vSpan(out)
}
func gateW(g val) float64 {
	switch g.k {
	case tvBit:
		return float64(g.i)
	case tvUnit:
		u := g.f
		if u < 0 {
			u = 0
		}
		if u > 1 {
			u = 1
		}
		return u
	case tvTrit:
		if g.i < 0 {
			return 0
		}
		if g.i > 0 {
			return 1
		}
		return 0.5
	default:
		return 0
	}
}
func softMux(w float64, pure, each val) val {
	if w >= 1-1e-6 {
		return pure
	}
	if w <= 1e-6 {
		return each
	}
	if pure.k == tvF32 || each.k == tvF32 || pure.k == tvI32 || each.k == tvI32 || pure.k == tvUnit || each.k == tvUnit {
		return vF32(w*asF(pure) + (1-w)*asF(each))
	}
	if w >= 0.5 {
		return pure
	}
	return each
}
func binAdd(l, r val) val {
	if l.k == tvF32 || r.k == tvF32 {
		return vF32(asF(l) + asF(r))
	}
	return vI32(asI(l) + asI(r))
}
func binSub(l, r val) val {
	if l.k == tvF32 || r.k == tvF32 {
		return vF32(asF(l) - asF(r))
	}
	return vI32(asI(l) - asI(r))
}
func binMul(l, r val) val {
	if l.k == tvF32 || r.k == tvF32 {
		return vF32(asF(l) * asF(r))
	}
	return vI32(asI(l) * asI(r))
}
func binCmp(op string, l, r val) val {
	lf, rf := asF(l), asF(r)
	ok := false
	switch op {
	case "<":
		ok = lf < rf
	case ">":
		ok = lf > rf
	case "<=":
		ok = lf <= rf
	case ">=":
		ok = lf >= rf
	case "==":
		ok = lf == rf
	case "!=":
		ok = lf != rf
	}
	if ok {
		return vBit(1)
	}
	return vBit(0)
}


// ---- Production ternary LLM kernels (v0.81+) ----
func clamp01f(x float64) float64 {
	if x < 0 {
		return 0
	}
	if x > 1 {
		return 1
	}
	return x
}
func biQuantizeAbsmean(xs val) val {
	n := len(xs.items)
	if n == 0 {
		return vSpan([]val{vSpan(nil), vF32(0)})
	}
	sumAbs := 0.0
	for _, x := range xs.items {
		v := asF(x)
		if v < 0 {
			v = -v
		}
		sumAbs += v
	}
	scale := sumAbs / float64(n)
	out := make([]val, n)
	if scale == 0 {
		for i := range out {
			out[i] = vTrit(0)
		}
		return vSpan([]val{vSpan(out), vF32(0)})
	}
	for i, x := range xs.items {
		r := asF(x) / scale
		t := 0
		if r >= 0.5 {
			t = 1
		} else if r <= -0.5 {
			t = -1
		}
		out[i] = vTrit(t)
	}
	return vSpan([]val{vSpan(out), vF32(scale)})
}
func biTritPackQuant(xs val) val {
	n := len(xs.items)
	if n == 0 {
		return vSpan([]val{vSpan(nil), vSpan(nil), vI32(0), vF32(0)})
	}
	sumAbs := 0.0
	for _, x := range xs.items {
		v := asF(x)
		if v < 0 {
			v = -v
		}
		sumAbs += v
	}
	scale := sumAbs / float64(n)
	trits := make([]val, n)
	if scale == 0 {
		for i := range trits {
			trits[i] = vTrit(0)
		}
	} else {
		for i, x := range xs.items {
			r := asF(x) / scale
			t := 0
			if r >= 0.5 {
				t = 1
			} else if r <= -0.5 {
				t = -1
			}
			trits[i] = vTrit(t)
		}
	}
	pos, neg, nn := packTritWords(trits)
	return vSpan([]val{u32SpanVals(pos), u32SpanVals(neg), vI32(nn), vF32(scale)})
}
func biLinearTrit(W, x, Mv, Kv, scaleV val) val {
	return biLinearTritMode(W, x, Mv, Kv, scaleV, false)
}
func biLinearTritBitplane(W, x, Mv, Kv, scaleV, flag val) val {
	use := asF(flag) != 0 || asI(flag) != 0
	return biLinearTritMode(W, x, Mv, Kv, scaleV, use)
}
// biLinearTritMode: scalar (4-unroll) or packed bitplane set-bit accumulate (v1.05).
func biLinearTritMode(W, x, Mv, Kv, scaleV val, bitplane bool) val {
	M, K := asI(Mv), asI(Kv)
	scale := asF(scaleV)
	out := make([]val, M)
	if M <= 0 || K <= 0 {
		return vSpan(out)
	}
	if bitplane {
		for i := 0; i < M; i++ {
			row := make([]val, K)
			for t := 0; t < K; t++ {
				row[t] = W.items[i*K+t]
			}
			pos, neg, _ := packTritWords(row)
			acc := mixedDotPlanesGo(pos, neg, x.items, K)
			out[i] = vF32(scale * acc)
		}
		return vSpan(out)
	}
	for i := 0; i < M; i++ {
		acc := 0.0
		t := 0
		base := i * K
		for ; t+4 <= K; t += 4 {
			acc += float64(clampTrit(asI(W.items[base+t]))) * asF(x.items[t])
			acc += float64(clampTrit(asI(W.items[base+t+1]))) * asF(x.items[t+1])
			acc += float64(clampTrit(asI(W.items[base+t+2]))) * asF(x.items[t+2])
			acc += float64(clampTrit(asI(W.items[base+t+3]))) * asF(x.items[t+3])
		}
		for ; t < K; t++ {
			acc += float64(clampTrit(asI(W.items[base+t]))) * asF(x.items[t])
		}
		out[i] = vF32(scale * acc)
	}
	return vSpan(out)
}
func mixedDotPlanesGo(pos, neg []uint32, x []val, n int) float64 {
	if n <= 0 {
		return 0
	}
	nw := (n + 31) / 32
	var acc float64
	w := 0
	for ; w+4 <= nw; w += 4 {
		acc += mixedWordGo(pos, neg, x, w, n, nw)
		acc += mixedWordGo(pos, neg, x, w+1, n, nw)
		acc += mixedWordGo(pos, neg, x, w+2, n, nw)
		acc += mixedWordGo(pos, neg, x, w+3, n, nw)
	}
	for ; w+2 <= nw; w += 2 {
		acc += mixedWordGo(pos, neg, x, w, n, nw)
		acc += mixedWordGo(pos, neg, x, w+1, n, nw)
	}
	for ; w < nw; w++ {
		acc += mixedWordGo(pos, neg, x, w, n, nw)
	}
	return acc
}
func mixedWordGo(pos, neg []uint32, x []val, w, n, nw int) float64 {
	var mask uint32 = 0xffffffff
	if w == nw-1 && n%32 != 0 {
		mask = (uint32(1) << uint(n%32)) - 1
	}
	var p, g uint32
	if w < len(pos) {
		p = pos[w] & mask
	}
	if w < len(neg) {
		g = neg[w] & mask
	}
	base := w * 32
	var acc float64
	for p != 0 {
		b := bits.TrailingZeros32(p)
		idx := base + b
		if idx < len(x) {
			acc += asF(x[idx])
		}
		p &^= 1 << uint(b)
	}
	for g != 0 {
		b := bits.TrailingZeros32(g)
		idx := base + b
		if idx < len(x) {
			acc -= asF(x[idx])
		}
		g &^= 1 << uint(b)
	}
	return acc
}
func biLinearTritGemm(A, B, Mv, Kv, Nv, scaleV val) val {
	M, _, N := asI(Mv), asI(Kv), asI(Nv)
	scale := asF(scaleV)
	C := biTritGemmBitplaneSIMD(A, B, Mv, Kv, Nv)
	out := make([]val, M*N)
	for i := 0; i < len(out); i++ {
		out[i] = vF32(scale * float64(asI(C.items[i])))
	}
	return vSpan(out)
}
func biScale(s, xs val) val {
	sv := asF(s)
	out := make([]val, len(xs.items))
	for i, x := range xs.items {
		out[i] = vF32(sv * asF(x))
	}
	return vSpan(out)
}
func biSpanScale(s, xs val) val { return biScale(s, xs) }
func biSpanMul(a, b val) val {
	n := len(a.items)
	if len(b.items) < n {
		n = len(b.items)
	}
	out := make([]val, n)
	for i := 0; i < n; i++ {
		out[i] = vF32(asF(a.items[i]) * asF(b.items[i]))
	}
	return vSpan(out)
}
func biRmsnorm(args ...val) val {
	if len(args) < 1 || args[0].k != tvSpan {
		return vSpan(nil)
	}
	x := args[0].items
	n := len(x)
	if n == 0 {
		return vSpan(nil)
	}
	eps := 1e-6
	if len(args) >= 2 {
		eps = asF(args[1])
	}
	ss := 0.0
	for _, v := range x {
		f := asF(v)
		ss += f * f
	}
	inv := 1.0 / math.Sqrt(ss/float64(n)+eps)
	out := make([]val, n)
	if len(args) >= 3 {
		g := args[2]
		if g.k == tvSpan {
			for i := 0; i < n; i++ {
				gi := 1.0
				if i < len(g.items) {
					gi = asF(g.items[i])
				}
				out[i] = vF32(asF(x[i]) * inv * gi)
			}
		} else {
			gi := asF(g)
			for i := 0; i < n; i++ {
				out[i] = vF32(asF(x[i]) * inv * gi)
			}
		}
	} else {
		for i := 0; i < n; i++ {
			out[i] = vF32(asF(x[i]) * inv)
		}
	}
	return vSpan(out)
}
func biSoftmax(xs val) val {
	n := len(xs.items)
	if n == 0 {
		return vSpan(nil)
	}
	m := asF(xs.items[0])
	for i := 1; i < n; i++ {
		if v := asF(xs.items[i]); v > m {
			m = v
		}
	}
	exps := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		e := math.Exp(asF(xs.items[i]) - m)
		exps[i] = e
		sum += e
	}
	out := make([]val, n)
	if sum == 0 {
		return vSpan(out)
	}
	inv := 1.0 / sum
	for i := 0; i < n; i++ {
		out[i] = vF32(exps[i] * inv)
	}
	return vSpan(out)
}
func biSilu(x val) val {
	if x.k == tvSpan {
		out := make([]val, len(x.items))
		for i, v := range x.items {
			f := asF(v)
			out[i] = vF32(f / (1.0 + math.Exp(-f)))
		}
		return vSpan(out)
	}
	f := asF(x)
	return vF32(f / (1.0 + math.Exp(-f)))
}
func biGelu(x val) val {
	gelu1 := func(f float64) float64 {
		return 0.5 * f * (1.0 + math.Tanh(0.7978845608028654*(f+0.044715*f*f*f)))
	}
	if x.k == tvSpan {
		out := make([]val, len(x.items))
		for i, v := range x.items {
			out[i] = vF32(gelu1(asF(v)))
		}
		return vSpan(out)
	}
	return vF32(gelu1(asF(x)))
}
func biRope(x, posV val, rest ...val) val {
	pos := asF(posV)
	base := 10000.0
	if len(rest) >= 1 {
		base = asF(rest[0])
		if base <= 0 {
			base = 10000.0
		}
	}
	n := len(x.items)
	out := make([]val, n)
	half := n / 2
	d := float64(n)
	if d < 2 {
		d = 2
	}
	for i := 0; i < half; i++ {
		expo := float64(2*i) / d
		theta := pos / math.Pow(base, expo)
		c, s := math.Cos(theta), math.Sin(theta)
		xi := asF(x.items[2*i])
		xj := asF(x.items[2*i+1])
		out[2*i] = vF32(xi*c - xj*s)
		out[2*i+1] = vF32(xi*s + xj*c)
	}
	if n%2 == 1 {
		out[n-1] = vF32(asF(x.items[n-1]))
	}
	return vSpan(out)
}
func biResidualAdd(a, b val) val { return biSpanAdd(a, b) }
func biAttnScores(q, K, dv val) val {
	d := asI(dv)
	nTok := len(K.items) / d
	scale := 1.0 / math.Sqrt(float64(d))
	logits := make([]val, nTok)
	for t := 0; t < nTok; t++ {
		acc := 0.0
		for i := 0; i < d; i++ {
			acc += asF(q.items[i]) * asF(K.items[t*d+i])
		}
		logits[t] = vF32(acc * scale)
	}
	return biSoftmax(vSpan(logits))
}
func biAttnValues(p, V, dv val) val {
	d := asI(dv)
	nTok := len(p.items)
	out := make([]val, d)
	for i := 0; i < d; i++ {
		acc := 0.0
		for t := 0; t < nTok; t++ {
			acc += asF(p.items[t]) * asF(V.items[t*d+i])
		}
		out[i] = vF32(acc)
	}
	return vSpan(out)
}
func biAttn(q, K, V, dv val) val {
	d := asI(dv)
	nTok := len(K.items) / d
	scale := 1.0 / math.Sqrt(float64(d))
	logits := make([]float64, nTok)
	m := -1e30
	for t := 0; t < nTok; t++ {
		acc := 0.0
		for i := 0; i < d; i++ {
			acc += asF(q.items[i]) * asF(K.items[t*d+i])
		}
		logits[t] = acc * scale
		if logits[t] > m {
			m = logits[t]
		}
	}
	exps := make([]float64, nTok)
	sum := 0.0
	for t := 0; t < nTok; t++ {
		e := math.Exp(logits[t] - m)
		exps[t] = e
		sum += e
	}
	inv := 0.0
	if sum != 0 {
		inv = 1.0 / sum
	}
	out := make([]val, d)
	for i := 0; i < d; i++ {
		acc := 0.0
		for t := 0; t < nTok; t++ {
			acc += (exps[t] * inv) * asF(V.items[t*d+i])
		}
		out[i] = vF32(acc)
	}
	return vSpan(out)
}
func biArgmax(xs val) val {
	if len(xs.items) == 0 {
		return vI32(0)
	}
	best := 0
	bv := asF(xs.items[0])
	for i := 1; i < len(xs.items); i++ {
		if v := asF(xs.items[i]); v > bv {
			bv, best = v, i
		}
	}
	return vI32(best)
}
var trinRNG atomic.Uint64

func init() {
	trinRNG.Store(0x9e3779b97f4a7c15)
}

func trinRNGNext() float64 {
	// xorshift64* — matches interpreter trinRNGNext
	for {
		old := trinRNG.Load()
		x := old
		if x == 0 {
			x = 0x9e3779b97f4a7c15
		}
		x ^= x >> 12
		x ^= x << 25
		x ^= x >> 27
		if trinRNG.CompareAndSwap(old, x) {
			return float64(x%1000000) / 1000000.0
		}
	}
}

func biSampleLogits(logits val, rest ...val) val {
	temp := 0.0
	if len(rest) >= 1 {
		temp = asF(rest[0])
	}
	if len(rest) >= 2 {
		s := uint64(asI(rest[1]))
		if s == 0 {
			s = 0x9e3779b97f4a7c15
		}
		trinRNG.Store(s)
	}
	if len(logits.items) == 0 {
		return vI32(0)
	}
	if temp <= 1e-8 {
		return biArgmax(logits)
	}
	// softmax(logits/temp) then categorical sample
	m := asF(logits.items[0]) / temp
	for i := 1; i < len(logits.items); i++ {
		v := asF(logits.items[i]) / temp
		if v > m {
			m = v
		}
	}
	exps := make([]float64, len(logits.items))
	sum := 0.0
	for i := range logits.items {
		e := math.Exp(asF(logits.items[i])/temp - m)
		exps[i] = e
		sum += e
	}
	r := trinRNGNext() * sum
	acc := 0.0
	for i, e := range exps {
		acc += e
		if r <= acc {
			return vI32(i)
		}
	}
	return vI32(len(logits.items) - 1)
}
func biSpanConcat(a, b val) val {
	out := make([]val, 0, len(a.items)+len(b.items))
	out = append(out, a.items...)
	out = append(out, b.items...)
	return vSpan(out)
}
func biKvNew(_ ...val) val { return vSpan(nil) }
func biKvAppend(cache, row val) val {
	out := make([]val, 0, len(cache.items)+len(row.items))
	out = append(out, cache.items...)
	out = append(out, row.items...)
	return vSpan(out)
}
func biKvLen(cache, dv val) val {
	d := asI(dv)
	if d <= 0 {
		return vI32(0)
	}
	return vI32(len(cache.items) / d)
}
func biKvRow(cache, idxV, dimV val) val {
	idx, dim := asI(idxV), asI(dimV)
	out := make([]val, dim)
	base := idx * dim
	for i := 0; i < dim; i++ {
		out[i] = vF32(asF(cache.items[base+i]))
	}
	return vSpan(out)
}
func biRngSeed(s val) val {
	x := uint64(asI(s))
	if x == 0 {
		x = 0x9e3779b97f4a7c15
	}
	trinRNG.Store(x)
	return vI32(0)
}
func biRngUniform(_ ...val) val {
	return vF32(trinRNGNext())
}
func biSampleTopk(logits val, kv val, rest ...val) val {
	k := asI(kv)
	temp := 0.0
	if len(rest) >= 1 {
		temp = asF(rest[0])
	}
	if len(rest) >= 2 {
		s := uint64(asI(rest[1]))
		if s == 0 {
			s = 0x9e3779b97f4a7c15
		}
		trinRNG.Store(s)
	}
	n := len(logits.items)
	if n == 0 {
		return vI32(0)
	}
	if k <= 0 || k > n {
		k = n
	}
	idxs := make([]int, n)
	for i := range idxs {
		idxs[i] = i
	}
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if asF(logits.items[idxs[j]]) > asF(logits.items[idxs[i]]) {
				idxs[i], idxs[j] = idxs[j], idxs[i]
			}
		}
	}
	top := idxs[:k]
	if temp <= 1e-8 {
		return vI32(top[0])
	}
	m := asF(logits.items[top[0]]) / temp
	for _, i := range top[1:] {
		v := asF(logits.items[i]) / temp
		if v > m {
			m = v
		}
	}
	weights := make([]float64, k)
	sum := 0.0
	for t, i := range top {
		e := math.Exp(asF(logits.items[i])/temp - m)
		weights[t] = e
		sum += e
	}
	r := trinRNGNext() * sum
	acc := 0.0
	for t, w := range weights {
		acc += w
		if r <= acc {
			return vI32(top[t])
		}
	}
	return vI32(top[k-1])
}
func biEmbedRow(tab, idxV, dimV val) val {
	idx, dim := asI(idxV), asI(dimV)
	out := make([]val, dim)
	base := idx * dim
	for i := 0; i < dim; i++ {
		out[i] = vF32(asF(tab.items[base+i]))
	}
	return vSpan(out)
}


func biLoadF32Csv(path val) val {
	b, err := os.ReadFile(fmtVal(path))
	if err != nil {
		fmt.Fprintf(os.Stderr, "load_f32_csv: %v\n", err)
		os.Exit(1)
	}
	fields := strings.FieldsFunc(string(b), func(r rune) bool {
		return r == ',' || r == ' ' || r == '\n' || r == '\t' || r == '\r' || r == ';'
	})
	out := make([]val, 0, len(fields))
	for _, f := range fields {
		if f == "" {
			continue
		}
		v, err := strconv.ParseFloat(f, 64)
		if err != nil {
			fmt.Fprintf(os.Stderr, "load_f32_csv parse %q: %v\n", f, err)
			os.Exit(1)
		}
		out = append(out, vF32(v))
	}
	return vSpan(out)
}
func biSaveF32Csv(path, xs val) val {
	parts := make([]string, len(xs.items))
	for i, x := range xs.items {
		parts[i] = strconv.FormatFloat(asF(x), 'g', -1, 64)
	}
	if err := os.WriteFile(fmtVal(path), []byte(strings.Join(parts, ",")), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "save_f32_csv: %v\n", err)
		os.Exit(1)
	}
	return vI32(len(parts))
}
func biLoadTritCsv(path val) val {
	b, err := os.ReadFile(fmtVal(path))
	if err != nil {
		fmt.Fprintf(os.Stderr, "load_trit_csv: %v\n", err)
		os.Exit(1)
	}
	fields := strings.FieldsFunc(string(b), func(r rune) bool {
		return r == ',' || r == ' ' || r == '\n' || r == '\t' || r == '\r' || r == ';'
	})
	out := make([]val, 0, len(fields))
	for _, f := range fields {
		if f == "" {
			continue
		}
		v, err := strconv.ParseInt(f, 10, 64)
		if err != nil {
			fv, err2 := strconv.ParseFloat(f, 64)
			if err2 != nil {
				fmt.Fprintf(os.Stderr, "load_trit_csv parse %q\n", f)
				os.Exit(1)
			}
			v = int64(fv)
		}
		out = append(out, vTrit(clampTrit(int(v))))
	}
	return vSpan(out)
}
func biQuantizeFileAbsmean(path val) val {
	p := fmtVal(path)
	b, err := os.ReadFile(p)
	if err != nil {
		fmt.Fprintf(os.Stderr, "quantize_file_absmean: %v\n", err)
		os.Exit(1)
	}
	fields := strings.FieldsFunc(string(b), func(r rune) bool {
		return r == ',' || r == ' ' || r == '\n' || r == '\t' || r == '\r' || r == ';'
	})
	xs := make([]val, 0, len(fields))
	for _, f := range fields {
		if f == "" {
			continue
		}
		v, err := strconv.ParseFloat(f, 64)
		if err != nil {
			fmt.Fprintf(os.Stderr, "quantize_file_absmean parse %q\n", f)
			os.Exit(1)
		}
		xs = append(xs, vF32(v))
	}
	q := biQuantizeAbsmean(vSpan(xs))
	// write companion sidecars (match interpreter quantize_file_absmean)
	trits := q.items[0]
	scale := asF(q.items[1])
	parts := make([]string, len(trits.items))
	for i, t := range trits.items {
		parts[i] = strconv.Itoa(asI(t))
	}
	_ = os.WriteFile(p+".trit.csv", []byte(strings.Join(parts, ",")), 0o644)
	_ = os.WriteFile(p+".scale.txt", []byte(strconv.FormatFloat(scale, 'g', -1, 64)), 0o644)
	return q
}


func biMha(q, K, V, dv, hv val) val {
	d, h := asI(dv), asI(hv)
	dh := d / h
	nTok := len(K.items) / d
	out := make([]val, d)
	for head := 0; head < h; head++ {
		scale := 1.0 / math.Sqrt(float64(dh))
		logits := make([]float64, nTok)
		m := -1e30
		for t := 0; t < nTok; t++ {
			acc := 0.0
			for i := 0; i < dh; i++ {
				acc += asF(q.items[head*dh+i]) * asF(K.items[t*d+head*dh+i])
			}
			logits[t] = acc * scale
			if logits[t] > m {
				m = logits[t]
			}
		}
		exps := make([]float64, nTok)
		sum := 0.0
		for t := 0; t < nTok; t++ {
			e := math.Exp(logits[t] - m)
			exps[t] = e
			sum += e
		}
		inv := 0.0
		if sum != 0 {
			inv = 1.0 / sum
		}
		for i := 0; i < dh; i++ {
			acc := 0.0
			for t := 0; t < nTok; t++ {
				acc += (exps[t] * inv) * asF(V.items[t*d+head*dh+i])
			}
			out[head*dh+i] = vF32(acc)
		}
	}
	return vSpan(out)
}

// ---- v0.83/0.85 weight importers (GGUF / safetensors + block dequant + mmap) ----
// Pure-Go readers embedded into compiled Trin programs.

type stInfo struct {
	Name   string
	Dtype  string
	Shape  []int64
	Offset int64
	Length int64
}

type stFile struct {
	Path    string
	Data    []byte
	Tensors map[string]stInfo
	Order   []string
	Mapped  bool
	mf      *mappedFile
}

type mappedFile struct {
	Data   []byte
	Path   string
	Mapped bool
	fd     *os.File
}

func openMapped(path string) (*mappedFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	st, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, err
	}
	size := st.Size()
	if size < 0 {
		_ = f.Close()
		return nil, fmt.Errorf("mmap: negative size")
	}
	if size == 0 {
		_ = f.Close()
		return &mappedFile{Data: nil, Path: path, Mapped: false}, nil
	}
	if size > 1<<40 {
		_ = f.Close()
		return nil, fmt.Errorf("mmap: file too large (%d)", size)
	}
	data, err := syscall.Mmap(int(f.Fd()), 0, int(size), syscall.PROT_READ, syscall.MAP_SHARED)
	if err != nil {
		b, rerr := os.ReadFile(path)
		_ = f.Close()
		if rerr != nil {
			return nil, fmt.Errorf("mmap: %v (fallback read: %v)", err, rerr)
		}
		return &mappedFile{Data: b, Path: path, Mapped: false}, nil
	}
	return &mappedFile{Data: data, Path: path, Mapped: true, fd: f}, nil
}

func (m *mappedFile) Close() error {
	if m == nil {
		return nil
	}
	var err error
	if m.Mapped && m.Data != nil {
		err = syscall.Munmap(m.Data)
		m.Data = nil
		m.Mapped = false
	} else {
		m.Data = nil
	}
	if m.fd != nil {
		if cerr := m.fd.Close(); cerr != nil && err == nil {
			err = cerr
		}
		m.fd = nil
	}
	return err
}

func openSafeTensors(path string) (*stFile, error) {
	mf, err := openMapped(path)
	if err != nil {
		return nil, err
	}
	b := mf.Data
	if len(b) < 8 {
		_ = mf.Close()
		return nil, fmt.Errorf("safetensors: file too short")
	}
	hlen := binary.LittleEndian.Uint64(b[0:8])
	if hlen == 0 || 8+hlen > uint64(len(b)) {
		_ = mf.Close()
		return nil, fmt.Errorf("safetensors: bad header length %d", hlen)
	}
	var header map[string]json.RawMessage
	if err := json.Unmarshal(b[8:8+hlen], &header); err != nil {
		_ = mf.Close()
		return nil, fmt.Errorf("safetensors: header json: %w", err)
	}
	dataBase := int64(8 + hlen)
	f := &stFile{Path: path, Data: b, Tensors: make(map[string]stInfo), Mapped: mf.Mapped, mf: mf}
	for name, raw := range header {
		if name == "__metadata__" {
			continue
		}
		var m map[string]any
		if err := json.Unmarshal(raw, &m); err != nil {
			_ = mf.Close()
			return nil, fmt.Errorf("safetensors: tensor %q: %w", name, err)
		}
		dtype, _ := m["dtype"].(string)
		var shape []int64
		if arr, ok := m["shape"].([]any); ok {
			for _, x := range arr {
				shape = append(shape, jsonInt64(x))
			}
		}
		var start, end int64
		if arr, ok := m["data_offsets"].([]any); ok && len(arr) >= 2 {
			start, end = jsonInt64(arr[0]), jsonInt64(arr[1])
		}
		if start < 0 || end < start {
			_ = mf.Close()
			return nil, fmt.Errorf("safetensors: tensor %q bad offsets", name)
		}
		info := stInfo{
			Name: name, Dtype: strings.ToUpper(dtype), Shape: shape,
			Offset: dataBase + start, Length: end - start,
		}
		f.Tensors[name] = info
		f.Order = append(f.Order, name)
	}
	return f, nil
}

func (f *stFile) close() error {
	if f == nil {
		return nil
	}
	var err error
	if f.mf != nil {
		err = f.mf.Close()
		f.mf = nil
	}
	f.Data = nil
	f.Mapped = false
	return err
}

func jsonInt64(v any) int64 {
	switch x := v.(type) {
	case float64:
		return int64(x)
	case json.Number:
		i, _ := x.Int64()
		return i
	case int64:
		return x
	case int:
		return int64(x)
	default:
		return 0
	}
}

func (f *stFile) list() []string {
	if len(f.Order) > 0 {
		return append([]string(nil), f.Order...)
	}
	out := make([]string, 0, len(f.Tensors))
	for k := range f.Tensors {
		out = append(out, k)
	}
	return out
}

func (f *stFile) loadF32(name string) ([]float32, []int64, error) {
	info, ok := f.Tensors[name]
	if !ok {
		return nil, nil, fmt.Errorf("safetensors: tensor %q not found", name)
	}
	if info.Offset+info.Length > int64(len(f.Data)) {
		return nil, nil, fmt.Errorf("safetensors: tensor %q OOB", name)
	}
	raw := f.Data[info.Offset : info.Offset+info.Length]
	vals, err := decodeNumeric(info.Dtype, raw)
	if err != nil {
		return nil, nil, err
	}
	return vals, info.Shape, nil
}

func (f *stFile) loadF32Window(name string, offset, count int) ([]float32, error) {
	info, ok := f.Tensors[name]
	if !ok {
		return nil, fmt.Errorf("safetensors: tensor %q not found", name)
	}
	if info.Offset+info.Length > int64(len(f.Data)) {
		return nil, fmt.Errorf("safetensors: tensor %q OOB", name)
	}
	raw := f.Data[info.Offset : info.Offset+info.Length]
	return decodeNumericWindow(info.Dtype, raw, offset, count)
}

func decodeNumericWindow(dtype string, raw []byte, offset, count int) ([]float32, error) {
	if offset < 0 || count < 0 {
		return nil, fmt.Errorf("safetensors window: bad range")
	}
	if count == 0 {
		return []float32{}, nil
	}
	switch strings.ToUpper(dtype) {
	case "F32", "FLOAT32":
		nElem := len(raw) / 4
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset*4:(offset+count)*4])
	case "F64", "FLOAT64":
		nElem := len(raw) / 8
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset*8:(offset+count)*8])
	case "F16", "FLOAT16", "BF16", "BFLOAT16", "I16", "INT16":
		nElem := len(raw) / 2
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset*2:(offset+count)*2])
	case "I8", "INT8", "U8", "UINT8":
		nElem := len(raw)
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset:offset+count])
	case "I32", "INT32":
		nElem := len(raw) / 4
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset*4:(offset+count)*4])
	case "I64", "INT64":
		nElem := len(raw) / 8
		if offset+count > nElem {
			return nil, fmt.Errorf("safetensors window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
		}
		return decodeNumeric(dtype, raw[offset*8:(offset+count)*8])
	default:
		return nil, fmt.Errorf("safetensors: unsupported dtype %s for window", dtype)
	}
}

func decodeNumeric(dtype string, raw []byte) ([]float32, error) {
	switch strings.ToUpper(dtype) {
	case "F32", "FLOAT32":
		if len(raw)%4 != 0 {
			return nil, fmt.Errorf("F32 length")
		}
		out := make([]float32, len(raw)/4)
		for i := range out {
			out[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
		}
		return out, nil
	case "F64", "FLOAT64":
		if len(raw)%8 != 0 {
			return nil, fmt.Errorf("F64 length")
		}
		out := make([]float32, len(raw)/8)
		for i := range out {
			out[i] = float32(math.Float64frombits(binary.LittleEndian.Uint64(raw[i*8:])))
		}
		return out, nil
	case "F16", "FLOAT16":
		if len(raw)%2 != 0 {
			return nil, fmt.Errorf("F16 length")
		}
		out := make([]float32, len(raw)/2)
		for i := range out {
			out[i] = float16ToF32(binary.LittleEndian.Uint16(raw[i*2:]))
		}
		return out, nil
	case "BF16", "BFLOAT16":
		if len(raw)%2 != 0 {
			return nil, fmt.Errorf("BF16 length")
		}
		out := make([]float32, len(raw)/2)
		for i := range out {
			bits := uint32(binary.LittleEndian.Uint16(raw[i*2:])) << 16
			out[i] = math.Float32frombits(bits)
		}
		return out, nil
	case "I8", "INT8":
		out := make([]float32, len(raw))
		for i, b := range raw {
			out[i] = float32(int8(b))
		}
		return out, nil
	case "U8", "UINT8":
		out := make([]float32, len(raw))
		for i, b := range raw {
			out[i] = float32(b)
		}
		return out, nil
	case "I16", "INT16":
		if len(raw)%2 != 0 {
			return nil, fmt.Errorf("I16 length")
		}
		out := make([]float32, len(raw)/2)
		for i := range out {
			out[i] = float32(int16(binary.LittleEndian.Uint16(raw[i*2:])))
		}
		return out, nil
	case "I32", "INT32":
		if len(raw)%4 != 0 {
			return nil, fmt.Errorf("I32 length")
		}
		out := make([]float32, len(raw)/4)
		for i := range out {
			out[i] = float32(int32(binary.LittleEndian.Uint32(raw[i*4:])))
		}
		return out, nil
	case "I64", "INT64":
		if len(raw)%8 != 0 {
			return nil, fmt.Errorf("I64 length")
		}
		out := make([]float32, len(raw)/8)
		for i := range out {
			out[i] = float32(int64(binary.LittleEndian.Uint64(raw[i*8:])))
		}
		return out, nil
	default:
		return nil, fmt.Errorf("safetensors: unsupported dtype %s", dtype)
	}
}

func float16ToF32(h uint16) float32 {
	sign := uint32(h>>15) & 1
	exp := uint32(h>>10) & 0x1f
	mant := uint32(h & 0x3ff)
	var fbits uint32
	switch exp {
	case 0:
		if mant == 0 {
			fbits = sign << 31
		} else {
			exp32 := int32(-14 + 127)
			for mant&0x400 == 0 {
				mant <<= 1
				exp32--
			}
			mant &= 0x3ff
			fbits = (sign << 31) | (uint32(exp32) << 23) | (mant << 13)
		}
	case 31:
		fbits = (sign << 31) | (0xff << 23) | (mant << 13)
	default:
		fbits = (sign << 31) | ((exp + (127 - 15)) << 23) | (mant << 13)
	}
	return math.Float32frombits(fbits)
}

const (
	ggmlF32  = 0
	ggmlF16  = 1
	ggmlQ4_0 = 2
	ggmlQ4_1 = 3
	ggmlQ5_0 = 6
	ggmlQ5_1 = 7
	ggmlQ80  = 8
	ggmlQ81  = 9
	ggmlQ2_K = 10
	ggmlQ3_K = 11
	ggmlQ4_K = 12
	ggmlQ5_K = 13
	ggmlQ6_K = 14
	ggmlQ8_K = 15
	ggmlIQ2_XXS = 16
	ggmlIQ2_XS = 17
	ggmlIQ3_XXS = 18
	ggmlIQ1_S = 19
	ggmlIQ1_M = 29
	ggmlIQ4_NL = 20
	ggmlIQ3_S = 21
	ggmlIQ2_S = 22
	ggmlIQ4_XS = 23
	ggmlI8   = 24
	ggmlI16  = 25
	ggmlI32  = 26
	ggmlI64  = 27
	ggmlF64  = 28
	ggmlBF16 = 30
	ggmlTQ1_0 = 34
	ggmlTQ2_0 = 35
	ggmlMXFP4 = 39
	ggmlNVFP4 = 40
)

type ggufTensorInfo struct {
	Name   string
	NDims  uint32
	Dims   []uint64
	Type   uint32
	Offset uint64
	Shard  int
}

type ggufFile struct {
	Path       string
	Version    uint32
	Alignment  uint64
	Data       []byte
	DataBase   int64
	Tensors    []ggufTensorInfo
	ByName     map[string]ggufTensorInfo
	Meta       map[string]string
	Mapped     bool
	mf         *mappedFile
	IsSharded  bool
	SplitCount uint16
	Shards     []*ggufFile
}

func openGGUF(path string) (*ggufFile, error) {
	mf, err := openMapped(path)
	if err != nil {
		return nil, err
	}
	b := mf.Data
	r := &byteR{b: b, i: 0}
	fail := func(err error) (*ggufFile, error) {
		_ = mf.Close()
		return nil, err
	}
	magic, err := r.u32()
	if err != nil {
		return fail(err)
	}
	if magic != 0x46554747 {
		return fail(fmt.Errorf("gguf: bad magic %08x", magic))
	}
	ver, err := r.u32()
	if err != nil {
		return fail(err)
	}
	if ver < 2 || ver > 3 {
		return fail(fmt.Errorf("gguf: unsupported version %d (need 2 or 3)", ver))
	}
	nTensors, err := r.u64()
	if err != nil {
		return fail(err)
	}
	nKV, err := r.u64()
	if err != nil {
		return fail(err)
	}
	f := &ggufFile{
		Path: path, Version: ver, Alignment: 32, Data: b,
		ByName: make(map[string]ggufTensorInfo), Meta: make(map[string]string),
		Mapped: mf.Mapped, mf: mf,
	}
	for i := uint64(0); i < nKV; i++ {
		key, err := r.str()
		if err != nil {
			return fail(fmt.Errorf("gguf kv key: %w", err))
		}
		vt, err := r.u32()
		if err != nil {
			return fail(err)
		}
		val, err := r.readValue(vt)
		if err != nil {
			return fail(fmt.Errorf("gguf kv %q: %w", key, err))
		}
		if key == "general.alignment" {
			if u, ok := val.(uint64); ok && u > 0 {
				f.Alignment = u
			} else if u32, ok := val.(uint32); ok && u32 > 0 {
				f.Alignment = uint64(u32)
			}
		}
		if s, ok := val.(string); ok {
			f.Meta[key] = s
		} else {
			f.Meta[key] = fmt.Sprint(val)
		}
	}
	for i := uint64(0); i < nTensors; i++ {
		name, err := r.str()
		if err != nil {
			return fail(err)
		}
		nDims, err := r.u32()
		if err != nil {
			return fail(err)
		}
		if nDims > 4 {
			return fail(fmt.Errorf("gguf: tensor %q n_dims=%d", name, nDims))
		}
		dims := make([]uint64, nDims)
		for d := uint32(0); d < nDims; d++ {
			dims[d], err = r.u64()
			if err != nil {
				return fail(err)
			}
		}
		typ, err := r.u32()
		if err != nil {
			return fail(err)
		}
		off, err := r.u64()
		if err != nil {
			return fail(err)
		}
		ti := ggufTensorInfo{Name: name, NDims: nDims, Dims: dims, Type: typ, Offset: off}
		f.Tensors = append(f.Tensors, ti)
		f.ByName[name] = ti
	}
	pos := r.i
	align := int64(f.Alignment)
	if align <= 0 {
		align = 32
	}
	if pos%align != 0 {
		pos = ((pos / align) + 1) * align
	}
	f.DataBase = pos
	return f, nil
}

func (f *ggufFile) close() error {
	if f == nil {
		return nil
	}
	var err error
	for i := 1; i < len(f.Shards); i++ {
		if f.Shards[i] != nil {
			if e := f.Shards[i].close(); e != nil && err == nil {
				err = e
			}
			f.Shards[i] = nil
		}
	}
	f.Shards = nil
	if f.mf != nil {
		if e := f.mf.Close(); e != nil && err == nil {
			err = e
		}
		f.mf = nil
	}
	f.Data = nil
	f.Mapped = false
	f.IsSharded = false
	return err
}

func (f *ggufFile) shardFile(ti ggufTensorInfo) *ggufFile {
	if f == nil {
		return nil
	}
	if ti.Shard <= 0 || ti.Shard >= len(f.Shards) || f.Shards[ti.Shard] == nil {
		return f
	}
	return f.Shards[ti.Shard]
}

func metaU16(meta map[string]string, key string) (uint16, bool) {
	if meta == nil {
		return 0, false
	}
	s, ok := meta[key]
	if !ok || s == "" {
		return 0, false
	}
	n, err := strconv.ParseUint(s, 10, 16)
	if err != nil {
		return 0, false
	}
	return uint16(n), true
}

func listShardPaths(path string, idx, nSplit int) ([]string, error) {
	if nSplit <= 0 {
		return nil, fmt.Errorf("gguf: invalid split count %d", nSplit)
	}
	dir := filepath.Dir(path)
	base := filepath.Base(path)
	lower := strings.ToLower(base)
	if !strings.HasSuffix(lower, ".gguf") {
		return nil, fmt.Errorf("gguf: shard path must end with .gguf: %s", path)
	}
	stem := base[:len(base)-len(".gguf")]
	candidates := []string{
		fmt.Sprintf("-%05d-of-%05d", idx, nSplit),
		fmt.Sprintf("-%d-of-%d", idx, nSplit),
	}
	var prefix string
	for _, suf := range candidates {
		if strings.HasSuffix(stem, suf) {
			prefix = stem[:len(stem)-len(suf)]
			break
		}
	}
	if prefix == "" {
		i := strings.LastIndex(stem, "-of-")
		if i <= 0 {
			return nil, fmt.Errorf("gguf: cannot parse split filename %s", base)
		}
		j := i - 1
		for j >= 0 && stem[j] >= '0' && stem[j] <= '9' {
			j--
		}
		if j < 0 || stem[j] != '-' {
			return nil, fmt.Errorf("gguf: cannot parse split idx in %s", base)
		}
		prefix = stem[:j]
		ofPart := stem[i+4:]
		got, err := strconv.Atoi(ofPart)
		if err != nil || got != nSplit {
			return nil, fmt.Errorf("gguf: filename of-count %q != split.count %d", ofPart, nSplit)
		}
	}
	out := make([]string, nSplit)
	for i := 0; i < nSplit; i++ {
		name := fmt.Sprintf("%s-%05d-of-%05d.gguf", prefix, i, nSplit)
		out[i] = filepath.Join(dir, name)
	}
	return out, nil
}

func openGGUFSharded(path string) (*ggufFile, error) {
	first, err := openGGUF(path)
	if err != nil {
		return nil, err
	}
	nSplit, hasCount := metaU16(first.Meta, "split.count")
	if !hasCount || nSplit <= 1 {
		return first, nil
	}
	idx, hasIdx := metaU16(first.Meta, "split.no")
	if !hasIdx {
		_ = first.close()
		return nil, fmt.Errorf("gguf: multi-shard missing split.no in %s", path)
	}
	paths, err := listShardPaths(path, int(idx), int(nSplit))
	if err != nil {
		_ = first.close()
		return nil, err
	}
	if idx != 0 {
		_ = first.close()
		first, err = openGGUF(paths[0])
		if err != nil {
			return nil, err
		}
		idx, hasIdx = metaU16(first.Meta, "split.no")
		if !hasIdx || idx != 0 {
			_ = first.close()
			return nil, fmt.Errorf("gguf: first shard %s must have split.no=0", paths[0])
		}
	}
	for i := range first.Tensors {
		first.Tensors[i].Shard = 0
		first.ByName[first.Tensors[i].Name] = first.Tensors[i]
	}
	first.Shards = make([]*ggufFile, nSplit)
	first.Shards[0] = nil
	first.IsSharded = true
	first.SplitCount = nSplit
	for si := 1; si < int(nSplit); si++ {
		sf, err := openGGUF(paths[si])
		if err != nil {
			_ = first.close()
			return nil, fmt.Errorf("gguf: open shard %d (%s): %w", si, paths[si], err)
		}
		got, ok := metaU16(sf.Meta, "split.no")
		if !ok || int(got) != si {
			_ = sf.close()
			_ = first.close()
			return nil, fmt.Errorf("gguf: shard %s has split.no=%v want %d", paths[si], sf.Meta["split.no"], si)
		}
		for _, ti := range sf.Tensors {
			if _, dup := first.ByName[ti.Name]; dup {
				_ = sf.close()
				_ = first.close()
				return nil, fmt.Errorf("gguf: duplicate tensor %q across shards", ti.Name)
			}
			ti.Shard = si
			first.Tensors = append(first.Tensors, ti)
			first.ByName[ti.Name] = ti
		}
		for k, v := range sf.Meta {
			if _, exists := first.Meta[k]; !exists {
				first.Meta[k] = v
			}
		}
		first.Shards[si] = sf
		if !sf.Mapped {
			first.Mapped = false
		}
	}
	if want, ok := metaU16(first.Meta, "split.tensors.count"); ok {
		if int(want) != len(first.Tensors) {
			_ = first.close()
			return nil, fmt.Errorf("gguf: split.tensors.count=%d but loaded %d tensors", want, len(first.Tensors))
		}
	}
	return first, nil
}

func (f *ggufFile) list() []string {
	out := make([]string, len(f.Tensors))
	for i, t := range f.Tensors {
		out[i] = t.Name
	}
	return out
}

func (f *ggufFile) loadF32(name string) ([]float32, []int64, error) {
	ti, ok := f.ByName[name]
	if !ok {
		return nil, nil, fmt.Errorf("gguf: tensor %q not found", name)
	}
	sf := f.shardFile(ti)
	nElem := uint64(1)
	shape := make([]int64, len(ti.Dims))
	for i, d := range ti.Dims {
		if d == 0 {
			return nil, nil, fmt.Errorf("gguf: zero dim")
		}
		nElem *= d
		shape[i] = int64(d)
	}
	base := sf.DataBase + int64(ti.Offset)
	if base < 0 || base > int64(len(sf.Data)) {
		return nil, nil, fmt.Errorf("gguf: bad data offset")
	}
	raw := sf.Data[base:]
	if need := ggmlRawBytes(ti.Type, int(nElem)); need > 0 {
		if int64(len(sf.Data))-base < int64(need) {
			return nil, nil, fmt.Errorf("gguf: tensor %q short", name)
		}
		raw = sf.Data[base : base+int64(need)]
	}
	vals, err := decodeGGML(ti.Type, raw, int(nElem))
	if err != nil {
		return nil, nil, err
	}
	return vals, shape, nil
}

func (f *ggufFile) loadF32Window(name string, offset, count int) ([]float32, error) {
	ti, ok := f.ByName[name]
	if !ok {
		return nil, fmt.Errorf("gguf: tensor %q not found", name)
	}
	sf := f.shardFile(ti)
	nElem := 1
	for _, d := range ti.Dims {
		if d == 0 {
			return nil, fmt.Errorf("gguf: zero dim")
		}
		nElem *= int(d)
	}
	if offset < 0 || count < 0 || offset+count > nElem {
		return nil, fmt.Errorf("gguf window OOB: offset=%d count=%d nElem=%d", offset, count, nElem)
	}
	base := sf.DataBase + int64(ti.Offset)
	if base < 0 || base > int64(len(sf.Data)) {
		return nil, fmt.Errorf("gguf: bad data offset")
	}
	raw := sf.Data[base:]
	if need := ggmlRawBytes(ti.Type, nElem); need > 0 {
		if int64(len(sf.Data))-base < int64(need) {
			return nil, fmt.Errorf("gguf: tensor %q short", name)
		}
		raw = sf.Data[base : base+int64(need)]
	}
	return DecodeGGMLWindow(ti.Type, raw, nElem, offset, count)
}

func ggmlRawBytes(typ uint32, nElem int) int {
	if nElem < 0 {
		return -1
	}
	switch typ {
	case ggmlF32, ggmlI32:
		return nElem * 4
	case ggmlF16, ggmlBF16, ggmlI16:
		return nElem * 2
	case ggmlF64, ggmlI64:
		return nElem * 8
	case ggmlI8:
		return nElem
	case ggmlQ4_0:
		return ((nElem + QK4_0 - 1) / QK4_0) * bsQ4_0
	case ggmlQ4_1:
		return ((nElem + QK4_1 - 1) / QK4_1) * bsQ4_1
	case ggmlQ5_0:
		return ((nElem + QK5_0 - 1) / QK5_0) * bsQ5_0
	case ggmlQ5_1:
		return ((nElem + QK5_1 - 1) / QK5_1) * bsQ5_1
	case ggmlQ80:
		return ((nElem + QK8_0 - 1) / QK8_0) * bsQ8_0
	case ggmlQ81:
		return ((nElem + QK8_1 - 1) / QK8_1) * bsQ8_1
	case ggmlQ2_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ2_K
	case ggmlQ3_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ3_K
	case ggmlQ4_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ4_K
	case ggmlQ5_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ5_K
	case ggmlQ6_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ6_K
	case ggmlQ8_K:
		return ((nElem + QK_K - 1) / QK_K) * bsQ8_K
	case ggmlIQ4_NL:
		return ((nElem + QK4_NL - 1) / QK4_NL) * bsIQ4_NL
	case ggmlTQ2_0:
		return ((nElem + QK_K - 1) / QK_K) * bsTQ2_0
	case ggmlIQ4_XS:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ4_XS
	case ggmlTQ1_0:
		return ((nElem + QK_K - 1) / QK_K) * bsTQ1_0
	case ggmlIQ2_XXS:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ2_XXS
	case ggmlIQ2_XS:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ2_XS
	case ggmlIQ2_S:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ2_S
	case ggmlIQ3_XXS:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ3_XXS
	case ggmlIQ3_S:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ3_S
	case ggmlIQ1_S:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ1_S
	case ggmlIQ1_M:
		return ((nElem + QK_K - 1) / QK_K) * bsIQ1_M
	case ggmlMXFP4:
		return ((nElem + QK_MXFP4 - 1) / QK_MXFP4) * bsMXFP4
	case ggmlNVFP4:
		return ((nElem + QK_NVFP4 - 1) / QK_NVFP4) * bsNVFP4
	default:
		return -1
	}
}


// ---- v0.84 GGUF block dequant (embedded) ----


// Block sizes (ggml-common.h).
const (
	QK4_0 = 32
	QK4_1 = 32
	QK5_0 = 32
	QK5_1 = 32
	QK8_0 = 32
	QK8_1 = 32
	QK4_NL = 32
	QK_K  = 256
)

const (
	bsQ4_0 = 2 + QK4_0/2
	bsQ4_1 = 2 + 2 + QK4_1/2
	bsQ5_0 = 2 + 4 + QK5_0/2
	bsQ5_1 = 2 + 2 + 4 + QK5_1/2
	bsQ8_0 = 2 + QK8_0
	bsQ8_1 = 2 + 2 + QK8_1
	bsQ2_K = 2*2 + QK_K/16 + QK_K/4
	bsQ3_K = 2 + QK_K/4 + QK_K/8 + 12
	bsQ4_K = 2*2 + 12 + QK_K/2
	bsQ5_K = 2*2 + 12 + QK_K/2 + QK_K/8
	bsQ6_K = 2 + QK_K/16 + 3*QK_K/4
	bsQ8_K = 4 + QK_K + (QK_K/16)*2
	bsIQ4_NL = 2 + QK4_NL/2
	bsIQ2_XXS = 2 + (QK_K/8)*2
	bsIQ2_XS = 2 + (QK_K/8)*2 + QK_K/32
	bsIQ2_S = 2 + QK_K/4 + QK_K/32 + QK_K/32
	bsIQ3_XXS = 2 + 3*(QK_K/8)
	bsIQ3_S = 2 + QK_K/4 + QK_K/32 + QK_K/8 + QK_K/64
	bsIQ1_S = 2 + QK_K/8 + (QK_K/32)*2
	bsIQ1_M = QK_K/8 + QK_K/16 + QK_K/32
	bsIQ4_XS = 2 + 2 + QK_K/64 + QK_K/2
	bsTQ1_0 = (QK_K-4*(QK_K/64))/5 + QK_K/64 + 2
	bsTQ2_0 = QK_K/4 + 2
	QK_MXFP4 = 32
	bsMXFP4 = 1 + QK_MXFP4/2
	QK_NVFP4 = 64
	QK_NVFP4_SUB = 16
	bsNVFP4 = QK_NVFP4/QK_NVFP4_SUB + QK_NVFP4/2
)


func f16bits(raw []byte, off int) float32 {
	return float16ToF32(binary.LittleEndian.Uint16(raw[off:]))
}

// dequantBlockQ4_0: block = half d + 16 nibble bytes; y = (q-8)*d
func dequantBlockQ4_0(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	qs := blk[2:]
	for j := 0; j < QK4_0/2; j++ {
		x0 := int(qs[j]&0x0F) - 8
		x1 := int(qs[j]>>4) - 8
		out[j] = float32(x0) * d
		out[j+QK4_0/2] = float32(x1) * d
	}
}

// dequantBlockQ4_1: half d, half m, 16 nibbles; y = q*d + m
func dequantBlockQ4_1(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	m := f16bits(blk, 2)
	qs := blk[4:]
	for j := 0; j < QK4_1/2; j++ {
		x0 := int(qs[j] & 0x0F)
		x1 := int(qs[j] >> 4)
		out[j] = float32(x0)*d + m
		out[j+QK4_1/2] = float32(x1)*d + m
	}
}

// dequantBlockQ5_0: half d, 4-byte qh, 16 nibbles
func dequantBlockQ5_0(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	qh := binary.LittleEndian.Uint32(blk[2:6])
	qs := blk[6:]
	for j := 0; j < QK5_0/2; j++ {
		xh0 := uint8(((qh >> uint(j+0)) << 4) & 0x10)
		xh1 := uint8((qh >> uint(j+12)) & 0x10)
		x0 := int((qs[j]&0x0F)|xh0) - 16
		x1 := int((qs[j]>>4)|xh1) - 16
		out[j] = float32(x0) * d
		out[j+QK5_0/2] = float32(x1) * d
	}
}

// dequantBlockQ5_1: half d, half m, 4-byte qh, 16 nibbles
func dequantBlockQ5_1(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	m := f16bits(blk, 2)
	qh := binary.LittleEndian.Uint32(blk[4:8])
	qs := blk[8:]
	for j := 0; j < QK5_1/2; j++ {
		xh0 := uint8(((qh >> uint(j+0)) << 4) & 0x10)
		xh1 := uint8((qh >> uint(j+12)) & 0x10)
		x0 := int((qs[j] & 0x0F) | xh0)
		x1 := int((qs[j] >> 4) | xh1)
		out[j] = float32(x0)*d + m
		out[j+QK5_1/2] = float32(x1)*d + m
	}
}

func dequantBlockQ8_0(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	qs := blk[2:]
	for j := 0; j < QK8_0; j++ {
		out[j] = float32(int8(qs[j])) * d
	}
}

func dequantBlockQ8_1(blk []byte, out []float32) {
	// d,s halves then int8 qs; dequant uses d*qs only (s is for dots)
	d := f16bits(blk, 0)
	qs := blk[4:]
	for j := 0; j < QK8_1; j++ {
		out[j] = float32(int8(qs[j])) * d
	}
}

// ---- K-quants (super-block 256) ----

func getScaleMinK4(j int, q []byte) (d, m uint8) {
	if j < 4 {
		return q[j] & 63, q[j+4] & 63
	}
	d = (q[j+4] & 0xF) | ((q[j-4] >> 6) << 4)
	m = (q[j+4] >> 4) | ((q[j-0] >> 6) << 4)
	return d, m
}

// block_q2_K layout: scales[16] | qs[64] | d,dmin halves  — wait:
// From ggml-common: scales[QK_K/16]=16, qs[QK_K/4]=64, then d,dmin
// sizeof = 2*half + 16 + 64 = 84. Order in struct: scales, qs, dm.
func dequantBlockQ2_K(blk []byte, out []float32) {
	scales := blk[0:16]
	q := blk[16 : 16+64]
	d := f16bits(blk, 16+64)
	minv := f16bits(blk, 16+64+2)
	y := 0
	is := 0
	qi := 0
	for n := 0; n < QK_K; n += 128 {
		shift := 0
		for j := 0; j < 4; j++ {
			sc := scales[is]
			is++
			dl := d * float32(sc&0xF)
			ml := minv * float32(sc>>4)
			for l := 0; l < 16; l++ {
				out[y] = dl*float32((q[qi+l]>>shift)&3) - ml
				y++
			}
			sc = scales[is]
			is++
			dl = d * float32(sc&0xF)
			ml = minv * float32(sc>>4)
			for l := 0; l < 16; l++ {
				out[y] = dl*float32((q[qi+16+l]>>shift)&3) - ml
				y++
			}
			shift += 2
		}
		qi += 32
	}
}

// block_q3_K: hmask[32] | qs[64] | scales[12] | d
func dequantBlockQ3_K(blk []byte, out []float32) {
	hm := blk[0:32]
	q := blk[32 : 32+64]
	scRaw := blk[32+64 : 32+64+12]
	dAll := f16bits(blk, 32+64+12)

	// unpack 6-bit scales into 16 int8 values (mirrors C)
	var aux [16]byte
	// memcpy first 12 then rearrange per dequantize_row_q3_K
	var a0, a1, a2, a3 uint32
	a0 = binary.LittleEndian.Uint32(scRaw[0:4])
	a1 = binary.LittleEndian.Uint32(scRaw[4:8])
	a2 = binary.LittleEndian.Uint32(scRaw[8:12])
	tmp := a2
	const kmask1 = 0x03030303
	const kmask2 = 0x0f0f0f0f
	a2 = ((a0 >> 4) & kmask2) | (((tmp >> 4) & kmask1) << 4)
	a3 = ((a1 >> 4) & kmask2) | (((tmp >> 6) & kmask1) << 4)
	a0 = (a0 & kmask2) | (((tmp >> 0) & kmask1) << 4)
	a1 = (a1 & kmask2) | (((tmp >> 2) & kmask1) << 4)
	binary.LittleEndian.PutUint32(aux[0:4], a0)
	binary.LittleEndian.PutUint32(aux[4:8], a1)
	binary.LittleEndian.PutUint32(aux[8:12], a2)
	binary.LittleEndian.PutUint32(aux[12:16], a3)
	scales := make([]int8, 16)
	for i := 0; i < 16; i++ {
		scales[i] = int8(aux[i])
	}

	y := 0
	qi := 0
	m := uint8(1)
	is := 0
	for n := 0; n < QK_K; n += 128 {
		shift := 0
		for j := 0; j < 4; j++ {
			dl := dAll * float32(int(scales[is])-32)
			is++
			for l := 0; l < 16; l++ {
				sub := int8(0)
				if hm[l]&m == 0 {
					sub = 4
				}
				out[y] = dl * float32(int8((q[qi+l]>>shift)&3)-sub)
				y++
			}
			dl = dAll * float32(int(scales[is])-32)
			is++
			for l := 0; l < 16; l++ {
				sub := int8(0)
				if hm[16+l]&m == 0 {
					sub = 4
				}
				out[y] = dl * float32(int8((q[qi+16+l]>>shift)&3)-sub)
				y++
			}
			shift += 2
			m <<= 1
		}
		qi += 32
	}
}

// block_q4_K: d,dmin | scales[12] | qs[128]
func dequantBlockQ4_K(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	minv := f16bits(blk, 2)
	scales := blk[4 : 4+12]
	q := blk[4+12:]
	y := 0
	is := 0
	for j := 0; j < QK_K; j += 64 {
		sc, m := getScaleMinK4(is+0, scales)
		d1 := d * float32(sc)
		m1 := minv * float32(m)
		sc, m = getScaleMinK4(is+1, scales)
		d2 := d * float32(sc)
		m2 := minv * float32(m)
		for l := 0; l < 32; l++ {
			out[y] = d1*float32(q[l]&0xF) - m1
			y++
		}
		for l := 0; l < 32; l++ {
			out[y] = d2*float32(q[l]>>4) - m2
			y++
		}
		q = q[32:]
		is += 2
	}
}

// block_q5_K: d,dmin | scales[12] | qh[32] | qs[128]
func dequantBlockQ5_K(blk []byte, out []float32) {
	d := f16bits(blk, 0)
	minv := f16bits(blk, 2)
	scales := blk[4 : 4+12]
	qh := blk[4+12 : 4+12+32]
	ql := blk[4+12+32:]
	y := 0
	is := 0
	u1, u2 := uint8(1), uint8(2)
	for j := 0; j < QK_K; j += 64 {
		sc, m := getScaleMinK4(is+0, scales)
		d1 := d * float32(sc)
		m1 := minv * float32(m)
		sc, m = getScaleMinK4(is+1, scales)
		d2 := d * float32(sc)
		m2 := minv * float32(m)
		for l := 0; l < 32; l++ {
			hi := 0
			if qh[l]&u1 != 0 {
				hi = 16
			}
			out[y] = d1*float32(int(ql[l]&0xF)+hi) - m1
			y++
		}
		for l := 0; l < 32; l++ {
			hi := 0
			if qh[l]&u2 != 0 {
				hi = 16
			}
			out[y] = d2*float32(int(ql[l]>>4)+hi) - m2
			y++
		}
		ql = ql[32:]
		is += 2
		u1 <<= 2
		u2 <<= 2
	}
}

// block_q6_K: ql[128] | qh[64] | scales[16] int8 | d
func dequantBlockQ6_K(blk []byte, out []float32) {
	ql := blk[0:128]
	qh := blk[128 : 128+64]
	sc := blk[128+64 : 128+64+16] // int8
	d := f16bits(blk, 128+64+16)
	y := 0
	qli, qhi, sci := 0, 0, 0
	for n := 0; n < QK_K; n += 128 {
		for l := 0; l < 32; l++ {
			is := l / 16
			q1 := int8((ql[qli+l]&0xF)|(((qh[qhi+l]>>0)&3)<<4)) - 32
			q2 := int8((ql[qli+32+l]&0xF)|(((qh[qhi+l]>>2)&3)<<4)) - 32
			q3 := int8((ql[qli+l]>>4)|(((qh[qhi+l]>>4)&3)<<4)) - 32
			q4 := int8((ql[qli+32+l]>>4)|(((qh[qhi+l]>>6)&3)<<4)) - 32
			s0 := float32(int8(sc[sci+is+0]))
			s2 := float32(int8(sc[sci+is+2]))
			s4 := float32(int8(sc[sci+is+4]))
			s6 := float32(int8(sc[sci+is+6]))
			out[y+l+0] = d * s0 * float32(q1)
			out[y+l+32] = d * s2 * float32(q2)
			out[y+l+64] = d * s4 * float32(q3)
			out[y+l+96] = d * s6 * float32(q4)
		}
		y += 128
		qli += 64
		qhi += 32
		sci += 8
	}
}

// block_q8_K: float d | qs[256] int8 | bsums[16] int16 (ignored for dequant)
func dequantBlockQ8_K(blk []byte, out []float32) {
	d := math.Float32frombits(binary.LittleEndian.Uint32(blk[0:4]))
	qs := blk[4 : 4+256]
	for j := 0; j < QK_K; j++ {
		out[j] = d * float32(int8(qs[j]))
	}
}

