func biWeightFileMapped(path val) val {
	p := fmtVal(path)
	lower := strings.ToLower(p)
	var mapped bool
	switch {
	case strings.HasSuffix(lower, ".gguf"):
		f, err := openGGUF(p)
		if err != nil {
			fmt.Fprintf(os.Stderr, "weight_file_mapped: %v\n", err)
			os.Exit(1)
		}
		mapped = f.Mapped
		_ = f.close()
	case strings.HasSuffix(lower, ".safetensors"):
		f, err := openSafeTensors(p)
		if err != nil {
			fmt.Fprintf(os.Stderr, "weight_file_mapped: %v\n", err)
			os.Exit(1)
		}
		mapped = f.Mapped
		_ = f.close()
	default:
		if f, err := openGGUF(p); err == nil {
			mapped = f.Mapped
			_ = f.close()
		} else if f, err := openSafeTensors(p); err == nil {
			mapped = f.Mapped
			_ = f.close()
		} else {
			fmt.Fprintf(os.Stderr, "weight_file_mapped: cannot open %s\n", p)
			os.Exit(1)
		}
	}
	if mapped {
		return vI32(1)
	}
	return vI32(0)
}


